-- LocalLearn server schema, MySQL 8.x
-- Apply through a migration runner while connected to the local server.
-- UUIDs are generated by the API so the same IDs work offline and across retries.

CREATE TABLE IF NOT EXISTS users (
  id CHAR(36) NOT NULL PRIMARY KEY,
  username VARCHAR(80) NOT NULL UNIQUE,
  display_name VARCHAR(160) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role ENUM('student','teacher','administrator') NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS classes (
  id CHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(160) NOT NULL,
  description TEXT NOT NULL,
  teacher_id CHAR(36) NOT NULL,
  room VARCHAR(80) NULL,
  term VARCHAR(80) NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  KEY ix_classes_teacher_active (teacher_id, active),
  CONSTRAINT fk_classes_teacher FOREIGN KEY (teacher_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS class_memberships (
  class_id CHAR(36) NOT NULL,
  user_id CHAR(36) NOT NULL,
  membership_role ENUM('student','teacher') NOT NULL,
  joined_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  removed_at DATETIME(6) NULL,
  PRIMARY KEY (class_id, user_id),
  KEY ix_memberships_user_active (user_id, removed_at),
  CONSTRAINT fk_memberships_class FOREIGN KEY (class_id) REFERENCES classes(id),
  CONSTRAINT fk_memberships_user FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Weekly timetable. Store the school's local timezone in deployment configuration;
-- weekday is ISO-8601 (1=Monday ... 7=Sunday).
CREATE TABLE IF NOT EXISTS class_meetings (
  id CHAR(36) NOT NULL PRIMARY KEY,
  class_id CHAR(36) NOT NULL,
  weekday TINYINT UNSIGNED NOT NULL,
  starts_at TIME NOT NULL,
  ends_at TIME NOT NULL,
  effective_from DATE NULL,
  effective_until DATE NULL,
  room VARCHAR(80) NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_meetings_class_weekday (class_id, weekday, active),
  CONSTRAINT fk_meetings_class FOREIGN KEY (class_id) REFERENCES classes(id),
  CONSTRAINT ck_meeting_weekday CHECK (weekday BETWEEN 1 AND 7),
  CONSTRAINT ck_meeting_times CHECK (ends_at > starts_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS assignments (
  id CHAR(36) NOT NULL PRIMARY KEY,
  class_id CHAR(36) NOT NULL,
  created_by CHAR(36) NOT NULL,
  title VARCHAR(200) NOT NULL,
  description TEXT NOT NULL,
  due_at DATETIME(6) NULL,
  allowed_submission_types JSON NOT NULL,
  allow_late BOOLEAN NOT NULL DEFAULT TRUE,
  allow_resubmission BOOLEAN NOT NULL DEFAULT FALSE,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  KEY ix_assignments_class_due (class_id, due_at),
  KEY ix_assignments_creator_updated (created_by, updated_at),
  CONSTRAINT fk_assignments_class FOREIGN KEY (class_id) REFERENCES classes(id),
  CONSTRAINT fk_assignments_creator FOREIGN KEY (created_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS assignment_resources (
  id CHAR(36) NOT NULL PRIMARY KEY,
  assignment_id CHAR(36) NOT NULL,
  display_name VARCHAR(255) NOT NULL,
  storage_key VARCHAR(500) NOT NULL,
  mime_type VARCHAR(120) NOT NULL,
  size_bytes BIGINT UNSIGNED NOT NULL,
  checksum_sha256 CHAR(64) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_assignment_resources_assignment (assignment_id),
  CONSTRAINT fk_resources_assignment FOREIGN KEY (assignment_id) REFERENCES assignments(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS submissions (
  id CHAR(36) NOT NULL PRIMARY KEY,
  assignment_id CHAR(36) NOT NULL,
  student_id CHAR(36) NOT NULL,
  attempt_number INT UNSIGNED NOT NULL,
  submitted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  status ENUM('submitted','returned','revision_requested','graded') NOT NULL DEFAULT 'submitted',
  grade_value DECIMAL(6,2) NULL,
  grade_label VARCHAR(40) NULL,
  graded_at DATETIME(6) NULL,
  graded_by CHAR(36) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  UNIQUE KEY uq_submission_attempt (assignment_id, student_id, attempt_number),
  KEY ix_submissions_student_status (student_id, status, submitted_at),
  CONSTRAINT fk_submissions_assignment FOREIGN KEY (assignment_id) REFERENCES assignments(id),
  CONSTRAINT fk_submissions_student FOREIGN KEY (student_id) REFERENCES users(id),
  CONSTRAINT fk_submissions_grader FOREIGN KEY (graded_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS submission_files (
  id CHAR(36) NOT NULL PRIMARY KEY,
  submission_id CHAR(36) NOT NULL,
  storage_key VARCHAR(500) NOT NULL,
  original_name VARCHAR(255) NOT NULL,
  mime_type VARCHAR(120) NOT NULL,
  size_bytes BIGINT UNSIGNED NOT NULL,
  checksum_sha256 CHAR(64) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_submission_files_submission (submission_id),
  CONSTRAINT fk_submission_files_submission FOREIGN KEY (submission_id) REFERENCES submissions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS assignment_feedback (
  id CHAR(36) NOT NULL PRIMARY KEY,
  submission_id CHAR(36) NOT NULL,
  teacher_id CHAR(36) NOT NULL,
  comment TEXT NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_feedback_submission_created (submission_id, created_at),
  CONSTRAINT fk_feedback_submission FOREIGN KEY (submission_id) REFERENCES submissions(id),
  CONSTRAINT fk_feedback_teacher FOREIGN KEY (teacher_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Curriculum structure stays separate from assignments so the course content can
-- travel with a learner even when the learner changes school or server.
CREATE TABLE IF NOT EXISTS curriculum_units (
  id CHAR(36) NOT NULL PRIMARY KEY,
  class_id CHAR(36) NOT NULL,
  title VARCHAR(200) NOT NULL,
  description TEXT NOT NULL,
  position INT UNSIGNED NOT NULL,
  starts_on DATE NULL,
  ends_on DATE NULL,
  learning_objectives JSON NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  UNIQUE KEY uq_unit_position (class_id, position),
  CONSTRAINT fk_units_class FOREIGN KEY (class_id) REFERENCES classes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS curriculum_lessons (
  id CHAR(36) NOT NULL PRIMARY KEY,
  unit_id CHAR(36) NOT NULL,
  title VARCHAR(200) NOT NULL,
  summary TEXT NOT NULL,
  position INT UNSIGNED NOT NULL,
  estimated_minutes SMALLINT UNSIGNED NULL,
  content_text LONGTEXT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  UNIQUE KEY uq_lesson_position (unit_id, position),
  CONSTRAINT fk_lessons_unit FOREIGN KEY (unit_id) REFERENCES curriculum_units(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS quizzes (
  id CHAR(36) NOT NULL PRIMARY KEY,
  class_id CHAR(36) NOT NULL,
  created_by CHAR(36) NOT NULL,
  title VARCHAR(200) NOT NULL,
  description TEXT NOT NULL,
  due_at DATETIME(6) NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  KEY ix_quizzes_class_due (class_id, due_at),
  CONSTRAINT fk_quizzes_class FOREIGN KEY (class_id) REFERENCES classes(id),
  CONSTRAINT fk_quizzes_creator FOREIGN KEY (created_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS quiz_questions (
  id CHAR(36) NOT NULL PRIMARY KEY,
  quiz_id CHAR(36) NOT NULL,
  position INT UNSIGNED NOT NULL,
  prompt TEXT NOT NULL,
  question_type ENUM('multiple_choice','short_answer') NOT NULL,
  options JSON NULL,
  correct_answer TEXT NULL,
  points DECIMAL(6,2) NOT NULL DEFAULT 1,
  UNIQUE KEY uq_question_position (quiz_id, position),
  CONSTRAINT fk_questions_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS quiz_attempts (
  id CHAR(36) NOT NULL PRIMARY KEY,
  quiz_id CHAR(36) NOT NULL,
  student_id CHAR(36) NOT NULL,
  answers JSON NOT NULL,
  score DECIMAL(6,2) NULL,
  status ENUM('submitted','ungraded','graded') NOT NULL DEFAULT 'submitted',
  graded_by CHAR(36) NULL,
  graded_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  KEY ix_quiz_attempts_student (student_id, quiz_id, created_at),
  CONSTRAINT fk_attempts_quiz FOREIGN KEY (quiz_id) REFERENCES quizzes(id),
  CONSTRAINT fk_attempts_student FOREIGN KEY (student_id) REFERENCES users(id),
  CONSTRAINT fk_attempts_grader FOREIGN KEY (graded_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Review events form a simple spaced-learning queue. The API calculates the next
-- due date; keep the schedule explainable and adjustable by teachers.
CREATE TABLE IF NOT EXISTS learning_reviews (
  id CHAR(36) NOT NULL PRIMARY KEY,
  student_id CHAR(36) NOT NULL,
  lesson_id CHAR(36) NOT NULL,
  due_at DATETIME(6) NOT NULL,
  completed_at DATETIME(6) NULL,
  recall_rating TINYINT UNSIGNED NULL,
  interval_days SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  source ENUM('lesson','quiz','teacher') NOT NULL DEFAULT 'lesson',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_reviews_student_due (student_id, completed_at, due_at),
  KEY ix_reviews_lesson (lesson_id, student_id),
  CONSTRAINT fk_reviews_student FOREIGN KEY (student_id) REFERENCES users(id),
  CONSTRAINT fk_reviews_lesson FOREIGN KEY (lesson_id) REFERENCES curriculum_lessons(id),
  CONSTRAINT ck_review_rating CHECK (recall_rating IS NULL OR recall_rating BETWEEN 1 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS calendar_events (
  id CHAR(36) NOT NULL PRIMARY KEY,
  class_id CHAR(36) NULL,
  created_by CHAR(36) NOT NULL,
  title VARCHAR(200) NOT NULL,
  description TEXT NULL,
  event_type ENUM('assignment','class','school','holiday','reminder') NOT NULL,
  starts_at DATETIME(6) NOT NULL,
  ends_at DATETIME(6) NULL,
  assignment_id CHAR(36) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_events_class_start (class_id, starts_at),
  CONSTRAINT fk_events_class FOREIGN KEY (class_id) REFERENCES classes(id),
  CONSTRAINT fk_events_creator FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT fk_events_assignment FOREIGN KEY (assignment_id) REFERENCES assignments(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS class_materials (
  id CHAR(36) NOT NULL PRIMARY KEY,
  class_id CHAR(36) NOT NULL,
  title VARCHAR(200) NOT NULL,
  material_type ENUM('syllabus','textbook','resource') NOT NULL,
  storage_key VARCHAR(500) NULL,
  content_text LONGTEXT NULL,
  mime_type VARCHAR(120) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  KEY ix_materials_class (class_id, material_type),
  CONSTRAINT fk_materials_class FOREIGN KEY (class_id) REFERENCES classes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Stable learner-owned records support a consent-based export/import between
-- schools. The API must verify transfer codes and omit private teacher notes.
CREATE TABLE IF NOT EXISTS learner_portfolio_items (
  id CHAR(36) NOT NULL PRIMARY KEY,
  learner_id CHAR(36) NOT NULL,
  item_type ENUM('learning_record','work_sample','credential','reflection') NOT NULL,
  title VARCHAR(200) NOT NULL,
  summary TEXT NOT NULL,
  content_json JSON NULL,
  storage_key VARCHAR(500) NULL,
  source_class_id CHAR(36) NULL,
  achieved_at DATETIME(6) NULL,
  visibility ENUM('private','shareable') NOT NULL DEFAULT 'private',
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  KEY ix_portfolio_learner_time (learner_id, achieved_at),
  CONSTRAINT fk_portfolio_learner FOREIGN KEY (learner_id) REFERENCES users(id),
  CONSTRAINT fk_portfolio_class FOREIGN KEY (source_class_id) REFERENCES classes(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS learner_transfer_codes (
  id CHAR(36) NOT NULL PRIMARY KEY,
  learner_id CHAR(36) NOT NULL,
  code_hash CHAR(64) NOT NULL,
  expires_at DATETIME(6) NOT NULL,
  used_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_transfer_learner_expiry (learner_id, expires_at, used_at),
  CONSTRAINT fk_transfer_learner FOREIGN KEY (learner_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS sync_operations (
  id CHAR(36) NOT NULL PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  operation_type VARCHAR(80) NOT NULL,
  entity_id CHAR(36) NOT NULL,
  payload_hash CHAR(64) NOT NULL,
  result_json JSON NULL,
  processed_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  KEY ix_sync_user_created (user_id, created_at),
  CONSTRAINT fk_sync_user FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Record applied migrations so restarts do not reapply schema changes.
CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(120) NOT NULL PRIMARY KEY,
  applied_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT IGNORE INTO schema_migrations (version) VALUES ('001_initial_schema');
